export const SWISS_BOUNDS = {
  minX: 28.9, maxX: 771.1,
  minY: 15.0, maxY: 485.0,
  minLng: 5.9559, maxLng: 10.4921,
  minLat: 45.8180, maxLat: 47.8084,
};

export function projectGps(lat, lng) {
  if (lat == null || lng == null) return null;
  const numLat = Number(lat);
  const numLng = Number(lng);
  if (isNaN(numLat) || isNaN(numLng)) return null;
  const x = SWISS_BOUNDS.minX + ((numLng - SWISS_BOUNDS.minLng) / (SWISS_BOUNDS.maxLng - SWISS_BOUNDS.minLng)) * (SWISS_BOUNDS.maxX - SWISS_BOUNDS.minX);
  const y = SWISS_BOUNDS.maxY - ((numLat - SWISS_BOUNDS.minLat) / (SWISS_BOUNDS.maxLat - SWISS_BOUNDS.minLat)) * (SWISS_BOUNDS.maxY - SWISS_BOUNDS.minY);
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
}

